package com.college.hospitalmanagement;
import java.time.LocalDate;import java.util.Map;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/dashboard") public class DashboardController{private final PatientRepository p;private final DoctorRepository d;private final NurseRepository n;private final AppointmentRepository a;private final BedRepository b;private final WardRepository w;private final RoomRepository r;private final DepartmentRepository dp;public DashboardController(PatientRepository p,DoctorRepository d,NurseRepository n,AppointmentRepository a,BedRepository b,WardRepository w,RoomRepository r,DepartmentRepository dp){this.p=p;this.d=d;this.n=n;this.a=a;this.b=b;this.w=w;this.r=r;this.dp=dp;}@GetMapping public Map<String,Object> summary(){long total=b.count(),occupied=b.findAll().stream().filter(x->"Occupied".equals(x.getStatus())).count();return Map.of("totalPatients",p.count(),"availableDoctors",d.findAll().stream().filter(x->"Active".equals(x.getStatus())).count(),"todayAppointments",a.findAll().stream().filter(x->LocalDate.now().equals(x.getAppointmentDate())).count(),"bedOccupancyPercent",total==0?0:Math.round(occupied*100.0/total),"totalNurses",n.count(),"totalDepartments",dp.count(),"totalWards",w.count(),"totalRooms",r.count(),"totalBeds",total,"availableBeds",b.findAll().stream().filter(x->"Available".equals(x.getStatus())).count());}}
